/* Present complete source frames. Image concepts never imply video approval. */
(()=>{
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const hero=s=>s.sequence?.heroIndex??1;
 const others=s=>[0,1,2,3].filter(i=>i!==hero(s));
 const frameView=(s,i)=>{const f=s.sequence?.frames?.[i],v=globalThis.AtlasFramePresentation?.[s.id]?.[i];return f&&v?{...f,crop:v[0],width:v[1],height:v[2]}:f;};
 const picture=(s,i,base='',cls='',small=false)=>{const f=frameView(s,i);if(!f)return '';const src=esc((globalThis.ATLAS_IMAGE_ASSET_BASE||base)+(small?f.thumbnail||f.src:f.src)),alt=esc(f.alt||s.name+' · '+f.label);if(f.crop){const [x,y,w,h]=f.crop;return `<span class="reference-panel ${cls}" style="--frame-ratio:${f.width/f.height};aspect-ratio:${f.width}/${f.height}"><img src="${src}" alt="${alt}" style="position:absolute;width:${100/w}%;height:${100/h}%;max-width:none;left:${-100*x/w}%;top:${-100*y/h}%;object-fit:fill" loading="lazy" decoding="async"></span>`;}return `<img class="${cls}" src="${src}" alt="${alt}" width="${f.width}" height="${f.height}" loading="lazy" decoding="async">`;};
 function strip(s,base=''){
  if(!s.sequence?.frames?.length)return '';
  return `<div class="sequence-strip" aria-label="Momentos da sequência">${others(s).map((i,n)=>`<button type="button" data-sequence="${esc(s.id)}" data-frame-index="${i}" aria-label="Ampliar ${esc(s.sequence.frames[i].label)} de ${esc(s.name)}">${picture(s,i,base,'',true)}<span>${String(i+1).padStart(2,'0')}</span></button>`).join('')}</div>`;
 }
 function sequence(s,base=''){
  if(!s.sequence?.frames?.length)return '';
  return `<section class="film-sheet" aria-label="Sequência visual de ${esc(s.name)}"><header class="film-heading"><h3>Como a história evolui</h3><p class="small">Siga a numeração 01 → 04, incluindo o quadro principal.</p></header><figure class="film-hero"><button class="frame-expand" data-sequence="${esc(s.id)}" data-frame-index="${hero(s)}" aria-label="Ampliar quadro principal">${picture(s,hero(s),base)}</button><figcaption>Quadro principal · ${String(hero(s)+1).padStart(2,'0')} · ${esc(s.sequence.frames[hero(s)].label.toLowerCase())}</figcaption></figure><div class="film-story"><p class="mobile-sequence-hint">Deslize para ver os momentos →</p><div class="film-steps">${others(s).map((i,n)=>{const f=s.sequence.frames[i];return `<figure><button class="frame-expand" data-sequence="${esc(s.id)}" data-frame-index="${i}" aria-label="Ampliar ${esc(f.label)}">${picture(s,i,base)}</button><figcaption><strong>${String(i+1).padStart(2,'0')} · ${esc(f.label)}</strong><p>${esc(f.caption||f.action)}</p></figcaption></figure>`}).join('')}</div><p class="film-sound">♪ ${esc(s.sequence.audio||'Voz, trilha e efeitos definidos pela direção do estilo.')}</p></div></section><p class="concept-note">Sequência conceitual de quatro quadros. Movimento, texto e fidelidade precisam ser conferidos na amostra em vídeo.</p>`;
 }
 function card(s,{base='',selected=false,favorite=false,compared=false,icon,imageStyle,previewMedia}){
  return `<article class="card${selected?' is-selected':''}" data-style-id="${esc(s.id)}"><button type="button" class="style-cover" data-detail="${esc(s.id)}" aria-label="Ver direção: ${esc(s.name)}"><span class="preview" style="${imageStyle(s)}">${previewMedia(s)}</span></button><div class="card-body"><div class="card-title-row"><h3><button class="card-title" data-detail="${esc(s.id)}">${esc(s.name)}</button></h3><button class="favorite" data-fav="${esc(s.id)}" aria-label="${favorite?'Remover dos':'Adicionar aos'} favoritos: ${esc(s.name)}" aria-pressed="${favorite}">${icon('heart')}</button></div><div class="card-meta"><span>${s.artDirection?'Referência realista + 4 momentos':s.sequence?'▧ 4 quadros':'Estudo visual'}</span></div>${strip(s,base)}<div class="card-actions"><button class="add-direction${selected?' chosen':''}" data-choose="${esc(s.id)}" aria-pressed="${selected}">${selected?'✓ Selecionado':'+ Escolher'}</button><label class="compare-toggle"><input type="checkbox" data-compare="${esc(s.id)}" ${compared?'checked':''}>Comparar</label></div></div></article>`;
 }
 function presenterStory(s,base=''){
  const plan=s.presenterEditing?.interactionPlan;if(!plan)return '';const beat=plan.beats[0];
  return `<section class="presenter-story" data-presenter-story="${esc(s.id)}" aria-label="Roteiro interativo de ${esc(s.name)}"><p class="eyebrow">${esc(plan.techniqueLabel)}</p><h3>Como a explicação acontece</h3><p>Explore os quatro momentos. A fala e os gestos serão ajustados ao seu vídeo.</p><div class="presenter-step-buttons" aria-label="Momentos do roteiro">${plan.beats.map((b,i)=>`<button type="button" class="outline" data-presenter-step="${i}" aria-pressed="${i===0}">${i+1}. ${esc(b.label)}</button>`).join('')}</div><div class="presenter-story-body"><div data-presenter-image-host>${picture(s,0,base)}</div><div aria-live="polite" aria-atomic="true"><h4 data-beat="label">${esc(beat.label)}</h4><p data-beat="purpose">${esc(beat.purpose)}</p><dl>${[['shotLanguage','Enquadramento e espaço'],['speechIntent','A fala conduz'],['presenterAction','A pessoa participa'],['graphicAction','A informação responde'],['soundIntent','Direção de som']].map(([key,label])=>`<dt>${label}</dt><dd data-beat="${key}">${esc(beat[key])}</dd>`).join('')}</dl></div></div><p class="small">Estudo de roteiro e composição, sem voz ou vídeo produzido. Tempos reais, contato e sincronismo serão conferidos na amostra.</p><details><summary>O que preparar para este estilo</summary><ul>${plan.requiredInputs.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p>${esc(plan.fallback)}</p></details></section>`;
 }
 function detail(s,{base='',requirementsHtml,readinessHtml}){
  return `<header class="direction-header"><p class="eyebrow">${esc(s.familyName)}</p><h2>${esc(s.name)}</h2><p>${esc(s.signature)}</p><div class="actions"><button class="primary" data-choose="${esc(s.id)}">Usar este estilo</button><button class="outline" data-similar="${esc(s.id)}">Procurar estilos parecidos</button></div></header>${sequence(s,base)}${presenterStory(s,base)}${s.presenterEditing?`<section class="direction-use"><h3>A pessoa participa da explicação</h3><p>Use seu vídeo gravado ou um avatar escolhido explicitamente. Preserve rosto, corpo, roupa, voz e ambiente original. Cenas cotidianas são a base; simulações externas precisam de referências verificadas e identificação.</p><p>Gráficos, transparências, movimento e brilhos suaves acompanham a explicação. O acabamento é para redes sociais: cor natural, luz equilibrada e textura leve conforme o original.</p><p>${esc(s.signature)}.</p><p class="small">${s.presenterEditing.requiredInputs.length?'Prepare: '+esc(s.presenterEditing.requiredInputs.join(' · '))+'.':'Prepare o vídeo original e confira os trechos da fala.'} O agente verifica os materiais antes de prometer o efeito.</p><a class="outline" href="${esc(base)}presenter-prompt.txt" download>Baixar pedido de edição com apresentador</a><p class="small">A ficha é uma direção visual. O recorte, o gesto e o sincronismo precisam ser demonstrados na amostra.</p></section>`:''}${s.advertising?`<section class="direction-use"><h3>Anúncio com história e voz</h3><p><strong>${esc(s.advertising.frameworkMeaning)}</strong> · 30–45 s sugeridos</p><p>Narração em português + legendas editáveis + chamada final.</p><p>Gancho: ${esc(s.advertising.hook)}</p><p>Fechamento: <strong>${esc(s.advertising.cta)}</strong></p><p class="small">O áudio será produzido após a pré-produção aprovada. Estas imagens não têm som.</p></section>`:''}<div class="direction-use"><h3>Quando usar</h3><p>${esc(s.uses)}</p><p class="small">Exemplo fictício: ${esc(s.sequence?.theme||s.exampleTopic)}. Complexidade indicativa: ${esc(s.complexity)}.</p></div><details class="direction-disclosure"><summary>Movimento, som e recursos de produção</summary><h3>Movimento proposto</h3><p>${esc(s.motion)}</p><h3>Recursos</h3><ul>${s.resources.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>Voz, trilha e efeitos</h3><p>${esc(s.audio?.voice)}</p><p>${esc(s.audio?.music)}</p><p>${esc(s.audio?.sfx)}</p><h3>O que demonstrar na amostra</h3><p>${esc(s.proof)}</p></details><details class="direction-disclosure"><summary>Materiais, ferramentas e fidelidade</summary>${requirementsHtml(s)}<p>${esc(s.requirements)}</p><p>${esc(s.preset.productFidelity)}</p>${readinessHtml(s)}<p class="small">${esc(s.note)}</p></details>`;
 }
 window.AtlasViews={esc,frameView,picture,strip,sequence,card,detail};
})();
